-- =============================================================================
-- 온톨로지 레지스트리·카탈로그 시드 — 생성: tools/gen_schema.py
-- 레지스트리는 항상 현재 릴리스만 담는다(upsert). 과거 버전은 onto.ontology_version.artifact_uri 의 TTL 번들로 보관 (리뷰 F17).
-- 트랜잭션은 apply 스크립트가 파일 단위로 묶는다(psql -1).
-- =============================================================================

ON CONFLICT (version_id) DO NOTHING;
ON CONFLICT (class_iri) DO UPDATE SET label_ko = EXCLUDED.label_ko, business_group = EXCLUDED.business_group, standard_clause = EXCLUDED.standard_clause, physical_table = EXCLUDED.physical_table, primary_key = EXCLUDED.primary_key, is_event = EXCLUDED.is_event, is_standard = EXCLUDED.is_standard, definition_ko = EXCLUDED.definition_ko, parent_class_iri = EXCLUDED.parent_class_iri, version_id = EXCLUDED.version_id;

ON CONFLICT (property_iri) DO UPDATE SET kind = EXCLUDED.kind, label_ko = EXCLUDED.label_ko, range_iri = EXCLUDED.range_iri, code_scheme = EXCLUDED.code_scheme, source_attribute = EXCLUDED.source_attribute, is_transitive = EXCLUDED.is_transitive, super_property_iri = EXCLUDED.super_property_iri, version_id = EXCLUDED.version_id;

DELETE FROM onto.link;   -- 링크는 매 릴리스 전체 교체

ON CONFLICT (dataset_id) DO UPDATE SET title_ko = EXCLUDED.title_ko, represents_class_iri = EXCLUDED.represents_class_iri, schema_version = EXCLUDED.schema_version;

ON CONFLICT (dataset_id, field_name) DO UPDATE SET label_ko = EXCLUDED.label_ko, data_type = EXCLUDED.data_type, maps_to_property_iri = EXCLUDED.maps_to_property_iri;

