INSERT INTO onto.ontology_version (version_id, ontology_iri, version_info, source, status) VALUES
  ('ksx9101-2025-v1.0-gen-0.2.0', 'https://ontology.impix.co.kr/ksx9101', '9101-1:2025-v1.0/gen-0.2.0', 'KSX9101-1_2025_온톨로지용v1.0_테이블정의서.xlsx + arcon_ext.ttl + lake_meta.ttl', 'DRAFT')
INSERT INTO onto.class (class_iri, local_name, label_ko, business_group, standard_clause, physical_table, primary_key, is_event, is_standard, definition_ko, parent_class_iri, version_id) VALUES
  ('https://ontology.impix.co.kr/ksx9101/Site', 'Site', '사업장', '기준정보', '7.4.1.1', 'site', 'EnterpriseID + SiteID', FALSE, TRUE, '회사 내 하위 관리단위로서의 사업장을 의미한다.', 'https://ontology.impix.co.kr/ksx9101/MasterDataObject', 'ksx9101-2025-v1.0-gen-0.2.0'),
  ('https://ontology.impix.co.kr/ksx9101/Plant', 'Plant', '공장', '기준정보', '7.4.1.2', 'plant', 'EnterpriseID + PlantID', FALSE, TRUE, '회사 내 하위 관리단위로서의 공장을 의미한다.', 'https://ontology.impix.co.kr/ksx9101/MasterDataObject', 'ksx9101-2025-v1.0-gen-0.2.0'),
  ('https://ontology.impix.co.kr/ksx9101/Department', 'Department', '부서', '기준정보', '7.4.1.3', 'department', 'EnterpriseID + DepartmentID', FALSE, TRUE, '회사 내 하위 관리 단위로서의 부서를 의미한다.', 'https://ontology.impix.co.kr/ksx9101/MasterDataObject', 'ksx9101-2025-v1.0-gen-0.2.0'),
  ('https://ontology.impix.co.kr/ksx9101/Personnel', 'Personnel', '사원', '기준정보', '7.4.1.4', 'personnel', 'EnterpriseID + PersonnelID', FALSE, TRUE, '사원코드, 사원명, 인적정보 등을 관리하는 사원 마스터를 의미한다. 일반적으로 HRMS(Human Resource Management System)에서 사용되지만 작업 스케줄링 또는 자원 할당에서 사용될 수도 있다.', 'https://ontology.impix.co.kr/ksx9101/MasterDataObject', 'ksx9101-2025-v1.0-gen-0.2.0'),
  ('https://ontology.impix.co.kr/ksx9101/CustomerPartyMaster', 'CustomerPartyMaster', '고객사', '기준정보', '7.4.1.5', 'customer_party_master', 'EnterpriseID + CustomerID', FALSE, TRUE, '고객사 코드, 고객사명, 사업자등록번호 등 고객사 정보를 관리하는 고객사 마스터를 의미한다.', 'https://ontology.impix.co.kr/ksx9101/MasterDataObject', 'ksx9101-2025-v1.0-gen-0.2.0'),
  ('https://ontology.impix.co.kr/ksx9101/VendorPartyMaster', 'VendorPartyMaster', '공급사', '기준정보', '7.4.1.6', 'vendor_party_master', 'EnterpriseID + VendorID', FALSE, TRUE, '공급사 코드, 공급사명, 사업자등록번호 등 공급사 정보를 관리하는 공급사 마스터를 의미한다.', 'https://ontology.impix.co.kr/ksx9101/MasterDataObject', 'ksx9101-2025-v1.0-gen-0.2.0'),
  ('https://ontology.impix.co.kr/ksx9101/CommonCodeMaster', 'CommonCodeMaster', '공통코드정보', '기준정보', '7.4.1.7', 'common_code_master', 'EnterpriseID + CommonCodeGroup + CommonCodeID', FALSE, TRUE, '애플리케이션 내에서 사용되는 각종 코드를 모아 놓은 통합 코드를 의미한다.', 'https://ontology.impix.co.kr/ksx9101/MasterDataObject', 'ksx9101-2025-v1.0-gen-0.2.0'),
  ('https://ontology.impix.co.kr/ksx9101/WorkCalendar', 'WorkCalendar', '달력', '기준정보', '7.4.1.8', 'work_calendar', 'EnterpriseID + CalendarID', FALSE, TRUE, '생산 현장의 달력을 의미한다. 단, 인사에서 사용하는 일반 달력과는 차이가 있다.', 'https://ontology.impix.co.kr/ksx9101/MasterDataObject', 'ksx9101-2025-v1.0-gen-0.2.0'),
  ('https://ontology.impix.co.kr/ksx9101/UOMGroup', 'UOMGroup', '단위그룹', '기준정보', '7.4.1.9', 'uom_group', 'EnterpriseID + UOMGroupID + UOMCode', FALSE, TRUE, '측정 단위의 집합을 의미한다. 일반적으로 재고관리 단위가 기본단위가 되며 특정 프로세스에서 변경될 수 있고, 재고에 반영될 때는 환산계수가 적용된다.', 'https://ontology.impix.co.kr/ksx9101/MasterDataObject', 'ksx9101-2025-v1.0-gen-0.2.0'),
  ('https://ontology.impix.co.kr/ksx9101/ItemMaster', 'ItemMaster', '품목마스터', '기준정보', '7.4.1.10', 'item_master', 'EnterpriseID + ItemID', FALSE, TRUE, '품목코드, 품목명, 규격 등과 각종 속성값을 관리하는 품목마스터를 의미한다. 단, 수량정보는 포함하지 않는다.', 'https://ontology.impix.co.kr/ksx9101/MasterDataObject', 'ksx9101-2025-v1.0-gen-0.2.0'),
  ('https://ontology.impix.co.kr/ksx9101/BOM', 'BOM', '자재명세서', '기준정보', '7.4.1.11', 'bom', 'EnterpriseID + BOMID + BOMRevisionNumber + ChildItemID', FALSE, TRUE, '품목을 구성하거나 품목을 생산하기 위해 투입되는 자재명세서를 의미한다.', 'https://ontology.impix.co.kr/arcon/DocumentLine', 'ksx9101-2025-v1.0-gen-0.2.0'),
  ('https://ontology.impix.co.kr/arcon/BOMHeader', 'BOMHeader', '자재명세서헤더', '기준정보', NULL, 'bom_header', 'EnterpriseID + BOMID + BOMRevisionNumber', FALSE, FALSE, '물리 보조 테이블(표준 외): 자재명세서의 자재명세서식별자+자재명세서버전 단위 헤더. 자재명세서 전체를 참조하는 FK를 위해 둠', 'https://ontology.impix.co.kr/arcon/DocumentHeader', 'ksx9101-2025-v1.0-gen-0.2.0'),
  ('https://ontology.impix.co.kr/ksx9101/Lot', 'Lot', '로트', '기준정보', '7.4.1.12', 'lot', 'EnterpriseID + LotID', FALSE, TRUE, '묶음 생산 단위의 정보를 의미한다.', 'https://ontology.impix.co.kr/ksx9101/MasterDataObject', 'ksx9101-2025-v1.0-gen-0.2.0'),
  ('https://ontology.impix.co.kr/ksx9101/Routing', 'Routing', '공정경로', '기준정보', '7.4.1.13', 'routing', 'EnterpriseID + RoutingID + OperationSequence', FALSE, TRUE, '생산 시 필요한 공정의 순서를 의미하며, 작업자, 기계를 포함한 경로와 관련된 모든 리소스, 활동에 대한 정보를 의미한다.', 'https://ontology.impix.co.kr/arcon/DocumentLine', 'ksx9101-2025-v1.0-gen-0.2.0'),
  ('https://ontology.impix.co.kr/arcon/RoutingHeader', 'RoutingHeader', '공정경로헤더', '기준정보', NULL, 'routing_header', 'EnterpriseID + RoutingID', FALSE, FALSE, '물리 보조 테이블(표준 외): 공정경로의 공정경로식별자 단위 헤더. 공정경로 전체를 참조하는 FK를 위해 둠', 'https://ontology.impix.co.kr/arcon/DocumentHeader', 'ksx9101-2025-v1.0-gen-0.2.0'),
  ('https://ontology.impix.co.kr/ksx9101/Operation', 'Operation', '공정', '기준정보', '7.4.1.14', 'operation', 'EnterpriseID + OperationID', FALSE, TRUE, '생산작업을 수행하는 작업장 또는 작업장 내 세부 작업단위를 의미한다.', 'https://ontology.impix.co.kr/ksx9101/MasterDataObject', 'ksx9101-2025-v1.0-gen-0.2.0'),
  ('https://ontology.impix.co.kr/ksx9101/Equipment', 'Equipment', '설비', '기준정보', '7.4.1.15', 'equipment', 'EnterpriseID + EquipmentID', FALSE, TRUE, '설비명, 설비유형 등 설비 관리 및 회사의 자산으로서 관리를 위한 설비정보를 의미한다.', 'https://ontology.impix.co.kr/ksx9101/MasterDataObject', 'ksx9101-2025-v1.0-gen-0.2.0'),
  ('https://ontology.impix.co.kr/ksx9101/OperationEquipment', 'OperationEquipment', '공정설비', '기준정보', '7.4.1.16', 'operation_equipment', 'EnterpriseID + OperationID + EquipmentID', FALSE, TRUE, '공정별 사용되는 설비 정보 데이터를 의미한다.', 'https://ontology.impix.co.kr/ksx9101/MasterDataObject', 'ksx9101-2025-v1.0-gen-0.2.0'),
  ('https://ontology.impix.co.kr/ksx9101/Carrier', 'Carrier', '캐리어', '기준정보', '7.4.1.17', 'carrier', 'EnterpriseID + CarrierID', FALSE, TRUE, '제조 공정 내 이동에 필요한 물리적 용기를 의미한다.', 'https://ontology.impix.co.kr/ksx9101/MasterDataObject', 'ksx9101-2025-v1.0-gen-0.2.0'),
  ('https://ontology.impix.co.kr/ksx9101/StockerInventory', 'StockerInventory', '저장소재공정보', '기준정보', '7.4.1.18', 'stocker_inventory', 'EnterpriseID + StockerID', FALSE, TRUE, '공장 내 공정 물류 저장소 정보를 의미한다. 이는 공정 내 물류 최적화를 위해 Lot Dispatcher를 사용하는데 SCS(StockerControlSystem), Dispatcher, MES 상호연동을 위해 존재한다.', 'https://ontology.impix.co.kr/ksx9101/MasterDataObject', 'ksx9101-2025-v1.0-gen-0.2.0'),
  ('https://ontology.impix.co.kr/ksx9101/WarehouseLocation', 'WarehouseLocation', '창고', '기준정보', '7.4.1.19', 'warehouse_location', 'EnterpriseID + WarehouseID', FALSE, TRUE, '재고를 모아 놓고 관리하는 위치를 의미한다.', 'https://ontology.impix.co.kr/ksx9101/MasterDataObject', 'ksx9101-2025-v1.0-gen-0.2.0'),
  ('https://ontology.impix.co.kr/ksx9101/Batch', 'Batch', '배치', '기준정보', '7.4.1.20', 'batch', 'EnterpriseID + BatchID', FALSE, TRUE, '배치 공정의 1회 실행으로 생산되고 있거나 생산된 물질의 단위를 의미한다. 원료를 정해진 양만큼 투입하여 일괄 처리하는 공정(배합, 반응, 발효, 열처리 등)의 생산 단위이며, 공급사에서 생산하여 납품한 구매품의 배치를 포함한다.', 'https://ontology.impix.co.kr/ksx9101/MasterDataObject', 'ksx9101-2025-v1.0-gen-0.2.0'),
  ('https://ontology.impix.co.kr/ksx9101/Line', 'Line', '라인', '기준정보', '7.4.1.21', 'line', 'EnterpriseID + LineID', FALSE, TRUE, '같은 공장 안에서 공정과 설비를 일정한 흐름으로 배치하여 특정 품목 또는 품목군을 생산하는 생산 단위를 의미한다. 라인은 공장에 속하며, 하나 이상의 공정과 설비로 구성된다.', 'https://ontology.impix.co.kr/ksx9101/MasterDataObject', 'ksx9101-2025-v1.0-gen-0.2.0'),
  ('https://ontology.impix.co.kr/ksx9101/Enterprise', 'Enterprise', '회사', '기준정보', '7.4.1.22', 'enterprise', 'EnterpriseID', FALSE, TRUE, '기업업무시스템 간 제조업무데이터를 교환하는 법인 단위의 회사를 의미한다. 회사는 하나 이상의 사업장으로 구성되며, 모든 명사 정보의 최상위 소유 범위가 된다.', 'https://ontology.impix.co.kr/ksx9101/MasterDataObject', 'ksx9101-2025-v1.0-gen-0.2.0'),
  ('https://ontology.impix.co.kr/ksx9101/ProjectMaster', 'ProjectMaster', '프로젝트마스터', '프로젝트관리', '7.4.2.1', 'project_master', 'EnterpriseID + ProjectID', FALSE, TRUE, '프로젝트 코드, 프로젝트명 등을 관리하는 프로젝트마스터를 의미한다. 주요 프로젝트 필드의 ProjectAccounting 관련 애플리케이션 활성화를 위한정보로 활용되기도 한다.', 'https://ontology.impix.co.kr/ksx9101/ProjectObject', 'ksx9101-2025-v1.0-gen-0.2.0'),
  ('https://ontology.impix.co.kr/ksx9101/EngineeringChangeOrder', 'EngineeringChangeOrder', '설계변경지시', '프로젝트관리', '7.4.2.2', 'engineering_change_order', 'EnterpriseID + EngineeringChangeOrderID', FALSE, TRUE, '제품의 설계를 변경하는 지시를 의미한다. 설계변경지시 수행 결과는 BOM 및 공정경로BOM에 반영된다.', 'https://ontology.impix.co.kr/ksx9101/ProjectObject', 'ksx9101-2025-v1.0-gen-0.2.0'),
  ('https://ontology.impix.co.kr/ksx9101/SalesOrder', 'SalesOrder', '수주오더', '판매관리', '7.4.3.1', 'sales_order', 'EnterpriseID + SalesOrderID', FALSE, TRUE, '고객사 주문정보를 의미한다.', 'https://ontology.impix.co.kr/ksx9101/SalesObject', 'ksx9101-2025-v1.0-gen-0.2.0'),
  ('https://ontology.impix.co.kr/ksx9101/SalesPlan', 'SalesPlan', '판매계획', '판매관리', '7.4.3.2', 'sales_plan', 'EnterpriseID + SalesPlanID', FALSE, TRUE, '고객사 Forecast정보 및 수요예측정보를 토대로 작성된 판매계획을 의미한다.', 'https://ontology.impix.co.kr/ksx9101/SalesObject', 'ksx9101-2025-v1.0-gen-0.2.0'),
  ('https://ontology.impix.co.kr/ksx9101/BasePrice', 'BasePrice', '기준가격', '구매관리', '7.4.4.1', 'base_price', 'EnterpriseID + ItemID + CurrencyCode', FALSE, TRUE, '구매요청 시 참조하기 위한 구매품의 기준가격 정보를 의미한다.', 'https://ontology.impix.co.kr/ksx9101/PurchaseObject', 'ksx9101-2025-v1.0-gen-0.2.0'),
  ('https://ontology.impix.co.kr/ksx9101/PurchaseRequisition', 'PurchaseRequisition', '구매요청', '구매관리', '7.4.4.2', 'purchase_requisition', 'EnterpriseID + PurchaseRequisitionID', FALSE, TRUE, '생산 또는 판매를 위해 수급되어야 할 품목을 요청하는 것을 의미한다(원부자재, 소모품, 상품 등).', 'https://ontology.impix.co.kr/ksx9101/PurchaseObject', 'ksx9101-2025-v1.0-gen-0.2.0'),
  ('https://ontology.impix.co.kr/ksx9101/PurchaseOrder', 'PurchaseOrder', '구매발주', '구매관리', '7.4.4.3', 'purchase_order', 'EnterpriseID + PurchaseOrderID', FALSE, TRUE, '구매자가 공급자의 품목을 구매하기 위한 주문을 의미한다.', 'https://ontology.impix.co.kr/ksx9101/PurchaseObject', 'ksx9101-2025-v1.0-gen-0.2.0'),
  ('https://ontology.impix.co.kr/ksx9101/MaterialArrival', 'MaterialArrival', '자재도착', '자재관리', '7.4.5.1', 'material_arrival', 'EnterpriseID + PurchaseDocumentNumber + PurchaseDocumentSequence + LotID', FALSE, TRUE, '자재가 입고 전 수입검사를 위해 도착한 정보를 의미한다.', 'https://ontology.impix.co.kr/ksx9101/MaterialObject', 'ksx9101-2025-v1.0-gen-0.2.0'),
  ('https://ontology.impix.co.kr/ksx9101/GoodsReceipt', 'GoodsReceipt', '입고', '자재관리', '7.4.5.2', 'goods_receipt', 'EnterpriseID + GoodsReceiptID + GoodsReceiptSequence', FALSE, TRUE, '구매 발주된 품목을 협력업체로부터 납품 받은 정보를 의미한다.', 'https://ontology.impix.co.kr/arcon/DocumentLine', 'ksx9101-2025-v1.0-gen-0.2.0'),
  ('https://ontology.impix.co.kr/ksx9101/GoodsIssue', 'GoodsIssue', '자재불출', '자재관리', '7.4.5.3', 'goods_issue', 'EnterpriseID + GoodsIssueID', FALSE, TRUE, '자재불출 요청된 자재를 불출하는 것을 의미한다(일반적으로 재고 관리주체가 다를 경우 창고관리부서에서 사용).', 'https://ontology.impix.co.kr/ksx9101/MaterialObject', 'ksx9101-2025-v1.0-gen-0.2.0'),
  ('https://ontology.impix.co.kr/ksx9101/ProductionPlanning', 'ProductionPlanning', '생산계획', '생산관리', '7.4.6.1', 'production_planning', 'EnterpriseID + ProductionPlanID', FALSE, TRUE, '특정 제품을 생산하기 위한 계획을 의미한다.', 'https://ontology.impix.co.kr/ksx9101/ProductionObject', 'ksx9101-2025-v1.0-gen-0.2.0'),
  ('https://ontology.impix.co.kr/ksx9101/ProductionOrder', 'ProductionOrder', '생산지시', '생산관리', '7.4.6.2', 'production_order', 'EnterpriseID + ProductionOrderID + ProductionOrderSequence', FALSE, TRUE, '특정 제품의 생산을 지시하는 정보를 의미한다.', 'https://ontology.impix.co.kr/ksx9101/ProductionObject', 'ksx9101-2025-v1.0-gen-0.2.0'),
  ('https://ontology.impix.co.kr/ksx9101/OperationStart', 'OperationStart', '착공', '생산관리', '7.4.6.3', 'operation_start', 'EnterpriseID + LotID + OperationID + OperationStartTime', TRUE, TRUE, '설비에 해당 공정의 생산을 지시한다.', 'https://ontology.impix.co.kr/arcon/Event', 'ksx9101-2025-v1.0-gen-0.2.0'),
  ('https://ontology.impix.co.kr/ksx9101/OperationEnd', 'OperationEnd', '완공', '생산관리', '7.4.6.4', 'operation_end', 'EnterpriseID + LotID + OperationID + OperationEndTime', TRUE, TRUE, '해당 공정의 생산 완료를 보고한다.', 'https://ontology.impix.co.kr/arcon/Event', 'ksx9101-2025-v1.0-gen-0.2.0'),
